#!/usr/bin/env node
/**
 * Generate build metadata for the Sylo About dialog.
 *
 * Writes apps/host/src/generated/build-info.ts (gitignored — regenerated by
 * npm postinstall and every build). Values are public-safe: version, git
 * commit, latest v* tag, build date.
 *
 * Fallbacks when git is unavailable (e.g. exported zip): commit/tag become
 * null and the UI hides those lines.
 */
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { execSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = join(__dirname, '..')
const outPath = join(root, 'apps', 'host', 'src', 'generated', 'build-info.ts')

function git(cmd) {
  try {
    return execSync(cmd, { cwd: root, stdio: ['ignore', 'pipe', 'ignore'] }).toString().trim()
  } catch {
    return null
  }
}

const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
const commit = git('git rev-parse --short=9 HEAD')
const tag = git('git describe --tags --abbrev=0 --match "v*"')
const committedAt = commit ? git('git log -1 --format=%cs') : null
const builtAt = new Date().toISOString().slice(0, 10)

const content = `/**
 * GENERATED by scripts/gen-build-info.mjs — do not edit or commit.
 * Regenerated on npm install (postinstall) and on every build.
 */
export const BUILD_INFO = {
  version: ${JSON.stringify(pkg.version)},
  commit: ${JSON.stringify(commit)},
  tag: ${JSON.stringify(tag)},
  committedAt: ${JSON.stringify(committedAt)},
  builtAt: ${JSON.stringify(builtAt)},
} as const
`

mkdirSync(dirname(outPath), { recursive: true })
writeFileSync(outPath, content, 'utf8')

const exists = existsSync(outPath)
console.log(`[gen-build-info] version=${pkg.version} commit=${commit ?? 'n/a'} tag=${tag ?? 'none'} -> ${exists ? 'written' : 'FAILED'}`)